mapper.select:
SELECT v.id, v.avid, v.title, v.cover_url, v.total_duration, v.episode_count, COALESCE((SELECT SUM(e.play_count) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0), 0) AS play_count, COALESCE((SELECT SUM(e.favorite_count) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0), 0) AS favorite_count, v.is_ongoing, v.video_status, v.create_time, c.name AS category_name, u.nike_name, u.avatar, u.uid, (SELECT CASE WHEN COUNT(*) = 0 THEN 0 WHEN SUM(CASE WHEN e.review_status = 0 THEN 1 ELSE 0 END) = COUNT(*) THEN 0 WHEN SUM(CASE WHEN e.review_status = 0 THEN 1 ELSE 0 END) > 0 THEN 1 ELSE 2 END FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0) AS review_status FROM public.video_info v LEFT JOIN public.category c ON v.category_id = c.id AND c.is_delete = 0 LEFT JOIN public.user_info u ON v.user_id = u.id
v.is_delete = 0
AND v.title LIKE CONCAT('%', #{title}, '%')
AND v.avid LIKE CONCAT('%', #{avid}, '%')
AND v.category_id = #{categoryId}
AND v.video_status = #{videoStates}
AND u.nike_name LIKE CONCAT('%', #{nickName}, '%')
AND v.is_ongoing = #{isOngoing}
AND u.uid LIKE CONCAT('%', #{uid}, '%')
ORDER BY ${orderColumn} ${orderDirection}
ORDER BY v.create_time DESC

SELECT v.id, v.avid, v.title, v.cover_url, v.total_duration, v.episode_count, COALESCE((SELECT SUM(e.play_count) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0), 0) AS play_count, COALESCE((SELECT SUM(e.favorite_count) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0), 0) AS favorite_count, (SELECT e.avid FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0 AND e.review_status = 1 ORDER BY e.episode_number DESC LIMIT 1) AS episode_avid, v.is_ongoing, v.create_time, v.user_id, v.category_id, c.name AS category_name, u.nike_name, u.avatar, u.uid FROM public.video_info v LEFT JOIN public.category c ON v.category_id = c.id AND c.is_delete = 0 LEFT JOIN public.user_info u ON v.user_id = u.id WHERE v.is_delete = 0 AND v.video_status = 2
AND v.category_id = #{categoryId}
AND v.user_id = #{userId}
AND (SELECT COUNT(*) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0 AND e.review_status = 1) >= 1 ORDER BY ${orderColumn} DESC

SELECT v.id FROM public.video_info v WHERE v.is_delete = 0 AND v.video_status = 2 AND v.id != #{videoId} AND (SELECT COUNT(*) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0 AND e.review_status = 1) >= 1 AND ( v.user_id = #{userId}
OR EXISTS ( SELECT 1 FROM unnest(string_to_array(#{tags}, ',')) AS t(tag) WHERE btrim(t.tag) != '' AND v.tags IS NOT NULL AND v.tags != '' AND EXISTS ( SELECT 1 FROM unnest(string_to_array(v.tags, ',')) AS vt(vtag) WHERE btrim(vt.vtag) = btrim(t.tag) ) )
) LIMIT #{limit}

SELECT v.id, v.avid, v.title, v.cover_url, v.total_duration, v.episode_count, COALESCE((SELECT SUM(e.play_count) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0), 0) AS play_count, COALESCE((SELECT SUM(e.favorite_count) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0), 0) AS favorite_count, (SELECT e.avid FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0 AND e.review_status = 1 ORDER BY e.episode_number DESC LIMIT 1) AS episode_avid, v.is_ongoing, v.create_time, v.user_id, v.tags, c.name AS category_name, u.nike_name, u.avatar, u.uid FROM public.video_info v LEFT JOIN public.category c ON v.category_id = c.id AND c.is_delete = 0 LEFT JOIN public.user_info u ON v.user_id = u.id WHERE v.is_delete = 0 AND v.video_status = 2 AND (SELECT COUNT(*) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0 AND e.review_status = 1) >= 1
AND v.id NOT IN
#{id}
ORDER BY favorite_count DESC LIMIT #{limit}

SELECT v.id, v.avid, v.title, v.cover_url, v.total_duration, v.episode_count, COALESCE((SELECT SUM(e.play_count) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0), 0) AS play_count, COALESCE((SELECT SUM(e.favorite_count) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0), 0) AS favorite_count, (SELECT e.avid FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0 AND e.review_status = 1 ORDER BY e.episode_number DESC LIMIT 1) AS episode_avid, v.is_ongoing, v.create_time, v.user_id, v.tags, c.name AS category_name, u.nike_name, u.avatar, u.uid FROM public.video_info v LEFT JOIN public.category c ON v.category_id = c.id AND c.is_delete = 0 LEFT JOIN public.user_info u ON v.user_id = u.id WHERE v.is_delete = 0 AND v.video_status = 2 AND (SELECT COUNT(*) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0 AND e.review_status = 1) >= 1
AND v.id NOT IN
#{id}
ORDER BY v.create_time DESC LIMIT #{limit}

SELECT v.id, v.avid, v.title, v.cover_url, v.total_duration, v.episode_count, COALESCE((SELECT SUM(e.play_count) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0), 0) AS play_count, COALESCE((SELECT SUM(e.favorite_count) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0), 0) AS favorite_count, (SELECT e.avid FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0 AND e.review_status = 1 ORDER BY e.episode_number DESC LIMIT 1) AS episode_avid, v.is_ongoing, v.create_time, v.user_id, v.category_id, v.tags, c.name AS category_name, u.nike_name, u.avatar, u.uid FROM public.video_info v LEFT JOIN public.category c ON v.category_id = c.id AND c.is_delete = 0 LEFT JOIN public.user_info u ON v.user_id = u.id WHERE v.is_delete = 0 AND v.video_status = 2 AND (SELECT COUNT(*) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0 AND e.review_status = 1) >= 1
OR v.category_id IN
#{cid}
OR EXISTS ( SELECT 1 FROM unnest(string_to_array(v.tags, ',')) AS vt(vtag) WHERE btrim(vt.vtag) IN
#{tag}
)
AND v.id NOT IN
#{id}
ORDER BY favorite_count DESC LIMIT #{limit}

SELECT v.avid, v.title, v.cover_url, v.video_status, v.is_ongoing, v.episode_count, COALESCE((SELECT SUM(e.play_count) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0), 0) AS play_count, COALESCE((SELECT SUM(e.favorite_count) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0), 0) AS favorite_count, (SELECT e.avid FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0 AND e.review_status = 1 ORDER BY e.episode_number DESC LIMIT 1) AS episode_avid, (SELECT e.avid FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0 ORDER BY e.episode_number DESC LIMIT 1) AS latest_episode_avid, v.create_time FROM public.video_info v WHERE v.is_delete = 0 AND v.user_id = #{userId}
AND v.video_status = #{videoStatus}
AND v.title LIKE CONCAT('%', #{title}, '%')
ORDER BY v.create_time DESC
